
function renderRedmineKatex() {
  // 1. Convert safe spans generated by math_dollars back to raw delimiters
  // This prevents Markdown from eating backslashes like \,
  document.querySelectorAll('span[data-math-style]').forEach(function(el) {
    var isDisplay = el.getAttribute('data-math-style') === 'display';
    var text = el.textContent;
    var start = isDisplay ? '$$' : '$';
    var end = isDisplay ? '$$' : '$';
    var textNode = document.createTextNode(start + text + end);
    el.parentNode.replaceChild(textNode, el);
  });

  // 2. Render all math on the page, matching the Activity screen behavior
  if (typeof renderMathInElement !== "undefined") {
    renderMathInElement(document.body, {
      delimiters: [
        {left: "$$", right: "$$", display: true},
        {left: "$", right: "$", display: false},
        {left: "\\[", right: "\\]", display: true},
        {left: "\\(", right: "\\)", display: false}
      ],
      throwOnError: false
    });
  }
}

document.addEventListener("DOMContentLoaded", renderRedmineKatex);

if (typeof jQuery !== "undefined") {
  jQuery(document).ajaxComplete(renderRedmineKatex);
}
